package server

import (
    "encoding/json"
    "net/http"
    "os"
    "frozen-final-service/internal/auth"
)

func New() http.Handler {
    mux := http.NewServeMux()
    mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json")
        _ = json.NewEncoder(w).Encode(map[string]string{"status":"ok", "project":"frozen-final-service", "database":"connection not checked by health endpoint"})
    })

    mux.Handle("GET /api/private", auth.Middleware(os.Getenv("AUTH_SECRET"), http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("authenticated")) })))
    return mux
}

package server

import (
    "net/http/httptest"
    "testing"
    "encoding/json"
)
func TestHealth(t *testing.T) {
    rr := httptest.NewRecorder()
    New().ServeHTTP(rr, httptest.NewRequest("GET", "/healthz", nil))
    if rr.Code != 200 { t.Fatalf("health: %d", rr.Code) }
    var body map[string]any
    if err:=json.Unmarshal(rr.Body.Bytes(), &body); err!=nil || body["status"]!="ok" { t.Fatal("invalid health response") }
}
